<?php $visits = ClientApi::data($api->request('GET','api/passport/visits')); $reservations = ClientApi::data($api->request('GET','api/reservations')); ?>
<section class="grid two-col"><article class="panel"><h2 class="section-title">Destinations visitées</h2><?php if (!$visits): ?><div class="empty"><div class="empty-icon">◷</div><h3>Votre carnet est encore vierge</h3><p>Les visites enregistrées dans votre passeport apparaîtront ici.</p></div><?php else: ?><div class="list"><?php foreach ($visits as $v): ?><div class="list-row"><div><div class="row-title"><?= client_h($v['nom'] ?? $v['destination'] ?? 'Visite') ?></div><div class="row-meta"><?= client_h(client_format_date($v['visite_le'] ?? null)) ?></div></div><span class="badge good">Visitée</span></div><?php endforeach; ?></div><?php endif; ?></article><article class="panel"><h2 class="section-title">Activité des réservations</h2><?php if (!$reservations): ?><div class="empty"><h3>Aucune activité</h3><p>Les changements de statut de vos réservations seront listés ici.</p></div><?php else: ?><div class="list"><?php foreach ($reservations as $r): ?><a class="list-row" href="?page=reservations&amp;id=<?= (int)$r['id'] ?>"><div><div class="row-title"><?= client_h($r['reference'] ?? '') ?> · <?= client_h($r['libelle_snapshot'] ?? '') ?></div><div class="row-meta"><?= client_h(client_format_date($r['created_at'] ?? null)) ?></div></div><?= client_status_badge((string)($r['statut'] ?? '')) ?></a><?php endforeach; ?></div><?php endif; ?></article></section>
